insert into private.phrase_patterns (criterion_key, mode, pattern) values
('sport_solo_rech','idx','J''aime quand l''autre pratique la musculation.||J''aime quand l''autre pratique le running.||J''aime quand l''autre pratique le vélo.||J''aime quand l''autre pratique la danse.||J''aime quand l''autre pratique le ski.||Le sport individuel m''importe peu.'),
('sport_groupe_rech','idx','J''aimerais faire du yoga ou du pilates avec lui ou elle.||J''aimerais faire de la randonnée avec lui ou elle.||J''aimerais faire de l''escalade avec lui ou elle.||J''aimerais faire des sports de combat avec lui ou elle.||Le sport collectif m''importe peu.'),
('sport_eau_rech','idx','Mon partenaire doit aimer les activités aquatiques.||Je n''attends pas de faire des sports aquatiques avec mon ou ma partenaire.'),
('sport_freq_rech','idx','Je veux quelqu''un de tranquille, pas sportif.||Je veux quelqu''un d''un peu sportif.||Je veux quelqu''un de très sportif.||Je veux un(e) athlète acharné(e).||Le niveau de sport m''importe peu.'),
('soc_extra_rech','idx','J''aime quand l''autre est très sociable.||J''aime quand l''autre aime recevoir.||J''aime quand l''autre est fêtard(e).||L''extraversion m''importe peu.'),
('soc_intro_rech','idx','J''apprécie quand l''autre est solitaire et calme.||J''apprécie quand l''autre préfère les petits comités.||J''apprécie quand l''autre est indépendant(e).||L''introversion m''importe peu.'),
('soc_reseau_rech','idx','J''admire les gens très « réseau ».||Je n''admire pas particulièrement les gens très « réseau ».||Le réseau professionnel m''importe peu.'),
('soc_famille_rech','idx','Je cherche quelqu''un de proche de sa famille.||Je cherche quelqu''un d''indépendant de sa famille.||Le lien familial m''importe peu.'),
('soc_amis_rech','idx','J''aime l''esprit bande d''amis.||Je préfère que le couple passe avant les amis.||La place des amis m''importe peu.'),
('fin_comport_rech','idx','Je supporterais mal un partenaire trop radin.||Je supporterais mal un partenaire trop flambeur.||Je supporterais mal un partenaire sans ambition financière.||Mon partenaire gère ses finances comme il ou elle le souhaite.'),
('fin_vision_rech','idx','Je cherche quelqu''un qui vise la sécurité financière.||Je cherche quelqu''un qui vise la prise de risque.||Je cherche quelqu''un qui vise une consommation responsable.||La vision financière m''importe peu.'),
('mob_transp_rech','idx','Mon partenaire doit être véhiculé.||Mon partenaire doit se déplacer de façon écologique.||Le mode de déplacement m''importe peu.'),
('animaux_rech','idx','Un partenaire avec des animaux, c''est génial.||Un partenaire avec des animaux, c''est non.||J''accepte seulement les chats et les chiens.||Les animaux m''importent peu.'),
('vice_conso_rech','idx','J''accepte que l''autre fume.||J''accepte une consommation régulière d''alcool.||Je n''accepte qu''une consommation occasionnelle.||J''exige quelqu''un de totalement sobre.||Je n''accepte pas la fumée.'),
('com_integ_rech','idx','J''aime que l''autre soit le centre de l''attention.||J''aime que l''autre soit discret et ne monopolise pas la parole.||J''aime que l''autre soit à l''écoute.||La façon de s''intégrer m''importe peu.'),
('com_drague_rech','idx','J''aime me faire aborder de façon cash et directe.||J''aime me faire aborder de façon subtile et diplomate.'),
('com_ecoute_rech','idx','J''ai besoin de quelqu''un qui m''écoute beaucoup.||J''ai besoin de quelqu''un qui parle beaucoup.||J''ai besoin d''un équilibre à parts égales.'),
('com_emot_rech','idx','Je veux que mon partenaire s''ouvre facilement.||Je veux que mon partenaire garde une part de mystère.||Je veux que mon partenaire soit pragmatique, peu démonstratif.||L''expression des émotions m''importe peu.'),
('com_humour_rech','sub','L''humour qui me fait rire est {}.'),
('com_canal_rech','idx','J''attends quelqu''un de très réactif par message.||J''attends quelqu''un qui aime les appels.||J''attends quelqu''un de détaché du téléphone, qui vit le moment présent.'),
('com_conflit_rech','idx','Lors d''une dispute, l''autre doit laisser couler.||Lors d''une dispute, l''autre doit dire les choses directement.||Lors d''une dispute, l''autre doit attendre que je revienne vers lui ou elle.'),
('com_franchis_rech','idx','J''attends une honnêteté brutale, toute la vérité.||J''attends une honnêteté empathique, dite avec tact.'),
('com_critiq_rech','idx','Avoir un partenaire susceptible me dérange.||Avoir un partenaire susceptible ne me dérange pas.'),
('com_empathie_rech','idx','L''empathie de l''autre est essentielle.||L''empathie de l''autre est un bonus.||L''empathie de l''autre m''importe peu.'),
('com_patienc_rech','idx','J''ai besoin de quelqu''un de patient avec moi.||Je n''ai pas besoin de quelqu''un de particulièrement patient.'),
('psy_confianc_rech','idx','Un partenaire sûr de lui m''attire.||Un partenaire sûr de lui m''intimide.||La confiance en soi de l''autre m''importe peu.'),
('psy_anxiete_rech','idx','Aider un partenaire anxieux me fait peur.||Je sais être rassurant(e) face à l''anxiété.'),
('psy_vision_rech','idx','Je veux m''entourer de quelqu''un de très positif.||Je veux m''entourer de quelqu''un de très réaliste et pragmatique.||La vision de la vie de l''autre m''importe peu.'),
('psy_curiosit_rech','idx','La curiosité intellectuelle de l''autre m''excite.||La curiosité intellectuelle de l''autre m''indiffère.'),
('psy_creativ_rech','idx','J''adore un esprit artistique chez l''autre.||Je ne recherche pas quelqu''un de créatif.||L''esprit artistique m''importe peu.'),
('psy_rigueur_rech','idx','J''aime que l''autre soit rigoureux et carré.||J''aime que l''autre soit flexible et adaptable.'),
('psy_competit_rech','idx','Un partenaire qui veut toujours gagner, c''est stimulant.||Un partenaire qui veut toujours gagner, c''est fatigant.'),
('psy_action_rech','idx','Je préfère un caractère fonceur.||Je préfère un caractère réfléchi et prudent.||Je préfère un caractère équilibré.'),
('psy_risque_rech','idx','J''ai besoin de quelqu''un qui me pousse à oser.||J''ai besoin de quelqu''un qui me sécurise.'),
('psy_ambition_rech','idx','L''ambition chez l''autre est indispensable.||L''ambition chez l''autre m''est égale.'),
('psy_humilite_rech','idx','Quelqu''un qui se vante beaucoup me fait fuir.||Quelqu''un qui se vante beaucoup ne me dérange pas.||Quelqu''un qui se vante beaucoup m''attire, j''y vois du charisme.'),
('psy_control_rech','idx','J''accepte que l''autre dirige souvent, j''aime me laisser porter.||Je veux une égalité parfaite, sans que l''autre dirige.'),
('psy_adaptab_rech','idx','L''adaptabilité de mon partenaire doit être parfaite.||L''adaptabilité de mon partenaire n''est pas un critère clé.'),
('psy_spontan_rech','idx','J''adore les surprises de dernière minute.||Je déteste les surprises de dernière minute.'),
('psy_discipli_rech','idx','Je cherche un partenaire très cadré.||Je cherche un partenaire plus léger, bohème.'),
('psy_persever_rech','idx','J''apprécie la résilience, quelqu''un qui ne lâche rien.||J''apprécie le lâcher-prise.'),
('psy_respons_rech','idx','Mon partenaire idéal doit être très responsable.||Mon partenaire idéal peut garder un esprit enfantin.'),
('val_but_rech','idx','Mon ou ma partenaire devrait viser la famille.||Mon ou ma partenaire devrait viser le travail et l''argent.||Mon ou ma partenaire devrait viser la liberté et les voyages.||C''est son choix, cela m''importe peu.'),
('val_fidelite_rech','idx','J''accepte une relation ouverte.||Je suis souple sur l''exclusivité.||J''attends une exclusivité modérée.||J''attends une forte exclusivité.||Une tromperie serait rédhibitoire.'),
('val_honnete_rech','idx','Je suis très souple sur l''honnêteté.||Je suis assez souple sur l''honnêteté.||J''attends une honnêteté modérée.||J''attends une grande honnêteté.||Je ne tolère aucun mensonge.'),
('val_religion_rech','idx','La croyance de l''autre m''importe peu.||La croyance de l''autre compte un peu.||La croyance de l''autre compte modérément.||La croyance de l''autre compte beaucoup.||La croyance de l''autre est obligatoire pour moi.'),
('val_spirit_rech','idx','L''autre doit être spirituel.||L''autre ne doit pas être spirituel.||La spiritualité de l''autre m''importe peu.'),
('val_politique_rech','idx','L''autre doit absolument avoir un engagement politique.||Un engagement politique chez l''autre est préférable.||L''engagement politique n''a pas d''importance, on en débattra.'),
('val_ecolo_rech','idx','Je veux un partenaire écologiste, c''est indispensable.||Un partenaire écologiste, si possible.||L''écologie chez l''autre m''importe peu.'),
('val_tradition_rech','idx','Mon partenaire doit respecter les traditions.||Mon partenaire ne doit pas être attaché aux traditions.||Le rapport aux traditions m''importe peu.'),
('val_culture_rech','idx','Je cherche quelqu''un de très cultivé.||Quelqu''un de très cultivé m''intimide.||Le niveau de culture m''importe peu.'),
('val_etudes_rech','idx','Je recherche au moins le baccalauréat.||Le diplôme ne compte pas pour moi.||Je recherche au minimum un Bac +3.||Je recherche au minimum un Bac +5.||Je recherche quelqu''un ayant un doctorat.||Je recherche un niveau supérieur au mien.||Je recherche un niveau inférieur au mien.||Je recherche un niveau identique au mien.'),
('val_morale_rech','idx','Je recherche avant tout l''altruisme.||Je recherche avant tout la loyauté.||Je recherche avant tout l''authenticité.||Je recherche avant tout la tolérance.||Je recherche avant tout la justice.||Je recherche avant tout le respect mutuel.||Je recherche avant tout l''indépendance.'),
('db_relation_rech','idx','Je cherche quelqu''un qui veut du sérieux exclusivement.||Je cherche quelqu''un qui veut une relation ouverte.||Je cherche quelqu''un qui veut s''amuser, sans lendemain.||Je suis ouvert(e) à tout type de rencontre.||Je cherche une amitié.'),
('db_mariage_rech','idx','Mon partenaire doit vouloir se marier un jour.||Mon partenaire ne doit pas vouloir se marier.||J''accepte quelqu''un d''indécis sur le mariage.'),
('db_enfants_rech','idx','Je veux rencontrer quelqu''un qui veut des enfants.||Je veux rencontrer quelqu''un qui ne veut pas d''enfants.||Je veux rencontrer quelqu''un qui a déjà des enfants.||Le projet d''enfants m''importe peu.'),
('cpl_dynamiq_rech','idx','J''accepterais que mon partenaire voie d''autres personnes.||Je n''accepterais pas que mon partenaire voie d''autres personnes.'),
('cpl_fusion_rech','idx','Je cherche quelqu''un qui fait tout avec moi.||Je cherche quelqu''un qui garde son indépendance.'),
('cpl_affect_rech','idx','J''aime que l''autre soit câlin et tactile en permanence.||Je n''aime pas trop les démonstrations d''affection.||J''aime une affection normale, sans excès.'),
('cpl_espace_rech','idx','Si mon partenaire part seul en week-end, ça me blesse.||Si mon partenaire part seul en week-end, je trouve ça très sain.'),
('cpl_jalous_rech','idx','Un partenaire un peu jaloux, je trouve ça mignon.||Un partenaire jaloux, je trouve ça toxique et je fuis.'),
('proj_prio_rech','idx','J''aimerais que sa priorité soit sa carrière.||J''aimerais que sa priorité soit notre famille.||J''aimerais qu''il ou elle trouve l''équilibre entre les deux.'),
('proj_statut_rech','idx','J''admire les partenaires entrepreneurs et ambitieux.||J''admire les partenaires salariés, stables et présents.||Le statut professionnel m''importe peu.'),
('proj_lieu_rech','idx','On devra se mettre d''accord pour vivre en ville.||On devra se mettre d''accord pour vivre à la campagne.||On ira là où le vent nous mène.'),
('proj_ancrage_rech','idx','J''ai besoin qu''il ou elle ait envie de s''installer et d''acheter.||J''ai besoin qu''il ou elle ait envie de bouger et de changer de pays.'),
('proj_retraite_rech','idx','L''idéal de vie à deux serait de prendre notre retraite tôt.||L''idéal de vie à deux serait de voyager autour du monde.||L''idéal de vie à deux serait de bâtir un empire.||L''idéal de vie à deux serait de vivre simplement d''amour.'),
('proj_rythme_rech','idx','Mon ou ma complice devra être prêt(e) à se poser tranquillement.||Mon ou ma complice devra être prêt(e) à partir à l''aventure avec moi.'),
('db_regime_rech','idx','Mon partenaire doit être vegan ou végétarien.||Mon partenaire mange ce qu''il veut.'),
('db_sex_or_rech','idx','Je cherche un(e) partenaire hétérosexuel(le).||Je cherche un(e) partenaire homosexuel(le).||Je cherche un(e) partenaire bisexuel(le).||Je cherche un(e) partenaire pansexuel(le).||Je cherche un(e) partenaire asexuel(le).||L''orientation sexuelle m''importe peu.');;
